`default_nettype none
// uart_apb.v : APB3 slave UART (8 data bits, optional parity, 1 stop bit). Generated by AI agent
//
// Plan (see reports/rtl.json):
//  - Outputs: prdata/pslverr comb (same-cycle function of the access phase and registered state),
//    txd/irq reg, pready constant 1.
//  - TX: FIFO -> 10-bit shift register, down counter per bit, txd driven by a flop.
//  - RX: 2-flop synchronizer + history flop, falling-edge start detect, mid-bit sampling,
//    frame finished at the middle of the stop bit (back-to-back frames, +-2 % tolerance).
//  - FIFOs: power-of-two depth, pointers with one extra wrap bit, memory arrays not reset.
module uart_apb #(
    parameter FIFO_DEPTH = 4,         //! bytes per FIFO, power of two, >= 2
    parameter ADDR_W     = 5,         //! paddr width, must be >= 5 (paddr[4:2] decodes the register)
    parameter DIV_RESET  = 868,       //! BAUD reset value, DIV_MIN .. 65535
    parameter DIV_MIN    = 4          //! smallest legal BAUD value, >= 2
) (
    input  wire              clk,      //! clock (APB PCLK)
    input  wire              rst_n,    //! synchronous reset, active-low
    input  wire              psel,     //! APB select
    input  wire              penable,  //! APB access phase
    input  wire              pwrite,   //! APB write
    input  wire [ADDR_W-1:0] paddr,    //! APB byte address
    input  wire [31:0]       pwdata,   //! APB write data
    output wire [31:0]       prdata,   //! comb: read data in read access cycle, else 0
    output wire              pready,   //! constant 1
    output wire              pslverr,  //! comb: error in access cycle, else 0
    input  wire              rxd,      //! UART input, asynchronous
    output wire              txd,      //! reg: UART output
    output wire              irq       //! reg: interrupt
);

    localparam        AW        = $clog2(FIFO_DEPTH);
    localparam        PW        = AW + 1;
    localparam [15:0] DIV_RESET_V = DIV_RESET;
    localparam [15:0] DIV_MIN_V   = DIV_MIN;

    localparam [2:0]  A_TXDATA = 3'd0;
    localparam [2:0]  A_RXDATA = 3'd1;
    localparam [2:0]  A_STATUS = 3'd2;
    localparam [2:0]  A_CTRL   = 3'd3;
    localparam [2:0]  A_BAUD   = 3'd4;

    // ------------------------------------------------------------------
    // APB decode
    // ------------------------------------------------------------------
    reg         bus_ok_ff;            // 0 in the cycle after a reset edge: no access is recognised

    wire        acc      = psel & penable & bus_ok_ff;
    wire        wr_acc   = acc & pwrite;
    wire        rd_acc   = acc & ~pwrite;
    wire [2:0]  a        = paddr[4:2];
    wire        sel_tx   = (a == A_TXDATA);
    wire        sel_rx   = (a == A_RXDATA);
    wire        sel_st   = (a == A_STATUS);
    wire        sel_ctrl = (a == A_CTRL);
    wire        sel_baud = (a == A_BAUD);
    wire        unmapped = a[2] & (a[1] | a[0]);       // 0x14 .. 0x1F

    wire        baud_ok  = (pwdata[15:0] >= DIV_MIN_V);

    always @(posedge clk) begin
        if (!rst_n) bus_ok_ff <= 1'b0;
        else        bus_ok_ff <= 1'b1;
    end

    // ------------------------------------------------------------------
    // CTRL / BAUD registers (next values are also used by the transmitter)
    // ------------------------------------------------------------------
    reg  [6:0]  ctrl_ff;
    reg  [15:0] baud_ff;
    wire [6:0]  ctrl_ns = (wr_acc & sel_ctrl) ? pwdata[6:0] : ctrl_ff;
    wire [15:0] baud_ns = (wr_acc & sel_baud & baud_ok) ? pwdata[15:0] : baud_ff;

    always @(posedge clk) begin
        if (!rst_n) begin
            ctrl_ff <= 7'd0;
            baud_ff <= DIV_RESET_V;
        end else begin
            ctrl_ff <= ctrl_ns;
            baud_ff <= baud_ns;
        end
    end

    wire ctrl_rx_en = ctrl_ff[1];

    // ------------------------------------------------------------------
    // TX FIFO
    // ------------------------------------------------------------------
    reg [7:0]    tx_mem [0:FIFO_DEPTH-1];
    reg [PW-1:0] txw_ff;
    reg [PW-1:0] txr_ff;

    wire tx_empty = (txw_ff == txr_ff);
    wire tx_full  = (txw_ff[AW-1:0] == txr_ff[AW-1:0]) & (txw_ff[AW] != txr_ff[AW]);
    wire tx_push  = wr_acc & sel_tx & ~tx_full;
    wire tx_start;                                     // pop, from the transmitter

    always @(posedge clk) begin
        if (tx_push) tx_mem[txw_ff[AW-1:0]] <= pwdata[7:0];
    end

    always @(posedge clk) begin
        if (!rst_n) begin
            txw_ff <= {PW{1'b0}};
            txr_ff <= {PW{1'b0}};
        end else begin
            if (tx_push)  txw_ff <= txw_ff + {{(PW-1){1'b0}}, 1'b1};
            if (tx_start) txr_ff <= txr_ff + {{(PW-1){1'b0}}, 1'b1};
        end
    end

    // ------------------------------------------------------------------
    // Transmitter
    // ------------------------------------------------------------------
    reg         txd_ff;
    reg         tx_busy_ff;
    reg  [15:0] tx_cnt_ff;      // cycles left in the current bit (1 = last cycle)
    reg  [3:0]  tx_left_ff;     // bits still to launch after the current one
    reg  [15:0] tx_div_ff;      // D of this frame (not reset: loaded at frame start)
    reg  [9:0]  tx_sh_ff;       // bits after the start bit, LSB first (not reset: loaded at start)

    // Frame parameters are taken from the values valid in the first cycle of the start bit.
    wire        tx_en_ns   = ctrl_ns[0];
    wire        tx_pen_ns  = ctrl_ns[2];
    wire        tx_podd_ns = ctrl_ns[3];
    wire [7:0]  tx_byte    = tx_mem[txr_ff[AW-1:0]];
    wire        tx_par     = (^tx_byte) ^ tx_podd_ns;
    wire        tx_bit_end = tx_busy_ff & (tx_cnt_ff == 16'd1);
    wire        tx_last    = tx_bit_end & (tx_left_ff == 4'd0);

    assign tx_start = tx_en_ns & ~tx_empty & (~tx_busy_ff | tx_last);

    always @(posedge clk) begin
        if (!rst_n) begin
            txd_ff     <= 1'b1;
            tx_busy_ff <= 1'b0;
            tx_cnt_ff  <= 16'd0;
            tx_left_ff <= 4'd0;
        end else if (tx_start) begin
            txd_ff     <= 1'b0;
            tx_busy_ff <= 1'b1;
            tx_cnt_ff  <= baud_ns;
            tx_left_ff <= tx_pen_ns ? 4'd10 : 4'd9;
        end else if (tx_busy_ff) begin
            if (tx_bit_end) begin
                if (tx_left_ff == 4'd0) begin
                    tx_busy_ff <= 1'b0;                // stop bit done, txd stays 1
                end else begin
                    txd_ff     <= tx_sh_ff[0];
                    tx_left_ff <= tx_left_ff - 4'd1;
                    tx_cnt_ff  <= tx_div_ff;
                end
            end else begin
                tx_cnt_ff <= tx_cnt_ff - 16'd1;
            end
        end
    end

    always @(posedge clk) begin                        // datapath, qualified by tx_busy_ff
        if (tx_start) begin
            tx_div_ff <= baud_ns;
            tx_sh_ff  <= tx_pen_ns ? {1'b1, tx_par, tx_byte} : {1'b1, 1'b1, tx_byte};
        end else if (tx_bit_end) begin
            tx_sh_ff  <= {1'b1, tx_sh_ff[9:1]};
        end
    end

    // ------------------------------------------------------------------
    // RX synchronizer
    // ------------------------------------------------------------------
    (* ASYNC_REG = "TRUE" *) reg rx_meta_ff;
    (* ASYNC_REG = "TRUE" *) reg rx_sync_ff;
    reg rx_prev_ff;

    always @(posedge clk) begin
        if (!rst_n) begin
            rx_meta_ff <= 1'b1;
            rx_sync_ff <= 1'b1;
            rx_prev_ff <= 1'b1;
        end else begin
            rx_meta_ff <= rxd;
            rx_sync_ff <= rx_meta_ff;
            rx_prev_ff <= rx_sync_ff;
        end
    end

    // ------------------------------------------------------------------
    // RX FIFO
    // ------------------------------------------------------------------
    reg [7:0]    rx_mem [0:FIFO_DEPTH-1];
    reg [PW-1:0] rxw_ff;
    reg [PW-1:0] rxr_ff;

    wire rx_empty = (rxw_ff == rxr_ff);
    wire rx_full  = (rxw_ff[AW-1:0] == rxr_ff[AW-1:0]) & (rxw_ff[AW] != rxr_ff[AW]);
    wire rx_pop   = rd_acc & sel_rx & ~rx_empty;
    wire rx_push;                                      // from the receiver
    reg  [7:0] rx_sh_ff;                               // not reset: qualified by the frame state

    always @(posedge clk) begin
        if (rx_push) rx_mem[rxw_ff[AW-1:0]] <= rx_sh_ff;
    end

    always @(posedge clk) begin
        if (!rst_n) begin
            rxw_ff <= {PW{1'b0}};
            rxr_ff <= {PW{1'b0}};
        end else begin
            if (rx_push) rxw_ff <= rxw_ff + {{(PW-1){1'b0}}, 1'b1};
            if (rx_pop)  rxr_ff <= rxr_ff + {{(PW-1){1'b0}}, 1'b1};
        end
    end

    // ------------------------------------------------------------------
    // Receiver
    // ------------------------------------------------------------------
    reg         rx_busy_ff;
    reg  [15:0] rx_cnt_ff;      // cycles to the next sample point (1 = sample now)
    reg  [15:0] rx_div_ff;      // D of this frame
    reg  [3:0]  rx_idx_ff;      // 0 start check, 1..8 data, 9 parity or stop, 10 stop
    reg         rx_pen_ff;
    reg         rx_podd_ff;
    reg         rx_pacc_ff;     // XOR of received data and parity bits

    wire rx_fall       = rx_prev_ff & ~rx_sync_ff;
    wire rx_tick       = rx_busy_ff & ctrl_rx_en & (rx_cnt_ff == 16'd1);
    wire rx_is_start   = (rx_idx_ff == 4'd0);
    wire rx_is_stop    = rx_pen_ff ? (rx_idx_ff == 4'd10) : (rx_idx_ff == 4'd9);
    wire rx_stop_tick  = rx_tick & rx_is_stop;
    wire rx_par_bad    = rx_pen_ff & (rx_pacc_ff != rx_podd_ff);
    wire rx_frame_ev   = rx_stop_tick & ~rx_sync_ff;
    wire rx_parity_ev  = rx_stop_tick & rx_par_bad;
    wire rx_good       = rx_stop_tick & rx_sync_ff & ~rx_par_bad;
    wire rx_ovr_ev     = rx_good & rx_full;
    assign rx_push     = rx_good & ~rx_full;

    always @(posedge clk) begin
        if (!rst_n) begin
            rx_busy_ff <= 1'b0;
            rx_cnt_ff  <= 16'd0;
            rx_idx_ff  <= 4'd0;
        end else if (!ctrl_rx_en) begin
            rx_busy_ff <= 1'b0;                        // disabled: abandon the frame
        end else if (!rx_busy_ff) begin
            if (rx_fall) begin
                rx_busy_ff <= 1'b1;
                rx_cnt_ff  <= {1'b0, baud_ff[15:1]};   // D/2: sample the middle of the start bit
                rx_idx_ff  <= 4'd0;
            end
        end else if (rx_tick) begin
            rx_cnt_ff <= rx_div_ff;
            if (rx_is_start) begin
                if (rx_sync_ff) rx_busy_ff <= 1'b0;    // false start
                else            rx_idx_ff  <= 4'd1;
            end else if (rx_is_stop) begin
                rx_busy_ff <= 1'b0;
            end else begin
                rx_idx_ff <= rx_idx_ff + 4'd1;
            end
        end else begin
            rx_cnt_ff <= rx_cnt_ff - 16'd1;
        end
    end

    always @(posedge clk) begin                        // frame parameters and data, qualified by rx_busy_ff
        if (!rx_busy_ff) begin
            rx_div_ff  <= baud_ff;
            rx_pen_ff  <= ctrl_ff[2];
            rx_podd_ff <= ctrl_ff[3];
            rx_pacc_ff <= 1'b0;
        end else if (rx_tick & ~rx_is_start & ~rx_is_stop) begin
            rx_pacc_ff <= rx_pacc_ff ^ rx_sync_ff;
        end
        if (rx_tick & ~rx_is_start & (rx_idx_ff < 4'd9))   // data bits 1..8 only
            rx_sh_ff <= {rx_sync_ff, rx_sh_ff[7:1]};
    end

    // ------------------------------------------------------------------
    // STATUS error bits (sticky, W1C, event wins)
    // ------------------------------------------------------------------
    reg  ovr_ff;
    reg  frm_ff;
    reg  par_ff;
    wire st_wr = wr_acc & sel_st;

    always @(posedge clk) begin
        if (!rst_n) begin
            ovr_ff <= 1'b0;
            frm_ff <= 1'b0;
            par_ff <= 1'b0;
        end else begin
            if (st_wr & pwdata[5]) ovr_ff <= 1'b0;
            if (st_wr & pwdata[6]) frm_ff <= 1'b0;
            if (st_wr & pwdata[7]) par_ff <= 1'b0;
            if (rx_ovr_ev)         ovr_ff <= 1'b1;
            if (rx_frame_ev)       frm_ff <= 1'b1;
            if (rx_parity_ev)      par_ff <= 1'b1;
        end
    end

    // ------------------------------------------------------------------
    // Read data / slave error
    // ------------------------------------------------------------------
    wire [31:0] status = {24'd0, par_ff, frm_ff, ovr_ff, tx_busy_ff, rx_empty, rx_full, tx_empty, tx_full};

    reg [31:0] prdata_c;
    always @* begin
        prdata_c = 32'd0;
        if (rd_acc) begin
            case (a)
                A_RXDATA: prdata_c = rx_empty ? 32'd0 : {24'd0, rx_mem[rxr_ff[AW-1:0]]};
                A_STATUS: prdata_c = status;
                A_CTRL:   prdata_c = {25'd0, ctrl_ff};
                A_BAUD:   prdata_c = {16'd0, baud_ff};
                default:  prdata_c = 32'd0;
            endcase
        end
    end

    wire err_c = acc & (unmapped
                      | (pwrite  & sel_tx   & tx_full)
                      | (~pwrite & sel_rx   & rx_empty)
                      | (pwrite  & sel_baud & ~baud_ok));

    assign prdata  = prdata_c;
    assign pslverr = err_c;
    assign pready  = 1'b1;
    assign txd     = txd_ff;

    // ------------------------------------------------------------------
    // Interrupt (registered: lags the sources by one cycle)
    // ------------------------------------------------------------------
    reg  irq_ff;
    wire irq_ns = (ctrl_ff[4] & ~rx_empty)
                | (ctrl_ff[5] & tx_empty)
                | (ctrl_ff[6] & (ovr_ff | frm_ff | par_ff));

    always @(posedge clk) begin
        if (!rst_n) irq_ff <= 1'b0;
        else        irq_ff <= irq_ns;
    end

    assign irq = irq_ff;

    // paddr[1:0] ignored by spec; pwdata[31:16] unused
    /* verilator lint_off UNUSED */
    wire unused_ok = &{1'b0, paddr, pwdata[31:16], pwdata[15:8]};
    /* verilator lint_on UNUSED */

endmodule

`default_nettype wire
